INSERT INTO contracts (counterparty_id, mandate_id, source, status) SELECT r.effective_cp, r.mandate_id, 'auto', 'open' FROM ( SELECT COALESCE(al.canonical_counterparty_id, own.id) AS effective_cp, CASE WHEN t.attributed_name IS NOT NULL THEN 'attributed' ELSE t.mandate_id END AS mandate_id, date_trunc('month', t.booking_date) AS month FROM transactions t LEFT JOIN counterparty_alias al ON al.identity_type = CASE WHEN t.attributed_name IS NOT NULL THEN 'name' WHEN t.creditor_id IS NOT NULL THEN 'creditor_id' END AND al.identity_value = CASE WHEN t.attributed_name IS NOT NULL THEN upper(trim(regexp_replace(normalize(t.attributed_name, NFC), '\s+', ' ', 'g'))) WHEN t.creditor_id IS NOT NULL THEN t.creditor_id END LEFT JOIN counterparties own ON own.identity_type = CASE WHEN t.attributed_name IS NOT NULL THEN 'name' WHEN t.creditor_id IS NOT NULL THEN 'creditor_id' END AND own.identity_value = CASE WHEN t.attributed_name IS NOT NULL THEN upper(trim(regexp_replace(normalize(t.attributed_name, NFC), '\s+', ' ', 'g'))) WHEN t.creditor_id IS NOT NULL THEN t.creditor_id END WHERE t.split_parent_content_hash IS NULL AND (t.attributed_name IS NOT NULL OR (t.creditor_id IS NOT NULL AND t.mandate_id IS NOT NULL)) AND COALESCE(al.canonical_counterparty_id, own.id) IS NOT NULL ) r GROUP BY r.effective_cp, r.mandate_id HAVING count(DISTINCT r.month) >= 2 ON CONFLICT (counterparty_id, mandate_id, product) DO NOTHING
